#![allow(dead_code)]
//! Shared DNxHD differential test surface (card 6.M-dnx, the
//! 6.M-opus `tests/opus` pattern): the **five-lane live oracle** of
//! the admission record (`docs/dependencies/records/
//! filmcraft-dnx-0.9.0.md` §D) — lanes generated by ffmpeg 7.1.5's
//! own `dnxhd` encoder (the corpus holds ZERO dnxhd lanes; the
//! record's method), decoded through the **wired
//! [`DnxDecoder`](codecs::video::dnx::DnxDecoder)**, compared
//! per-plane against ffmpeg's own decode.
//!
//! Test-side verification tooling in the 2.B4 sense: its
//! correctness is pinned by the recorded expectations it is checked
//! against (the record's committed per-lane reference MD5s in
//! `tools/vta/dnx/evidence/lane-md5s.txt`, and the record's §D
//! numbers), never trusted blind.
//!
//! The ratified tolerance class (Lead, worklog 6.VTA-DNX-RATIFY):
//! **maxΔ ≤ 2 LSB + sign balance + byte-count parity** — VC-3's
//! exact-f32 IDCT vs ffmpeg's integer IDCT makes bit-exactness
//! unreachable in principle; ±2 with balanced ±1 bulk is the
//! ceiling.

use std::path::{Path, PathBuf};

use codec_api::prelude::*;
use codecs::video::dnx::{DnxDecoder, DnxPicture};
use media_types::{EngineError, Frame, Packet};

/// Where generated lanes live (temp-resident, the corpus
/// convention; kept after the run for Lead verification).
fn lane_dir() -> PathBuf {
    let dir = std::env::temp_dir().join("lumen-dnx-diff");
    let _ignored = std::fs::create_dir_all(&dir);
    dir
}

/// Whether an `ffmpeg` binary is reachable (the live oracle).
pub fn ffmpeg_available() -> bool {
    std::process::Command::new("ffmpeg")
        .arg("-version")
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status()
        .is_ok_and(|s| s.success())
}

/// Run ffmpeg to completion; `unreachable!` on any failure (the
/// oracle is a test-side tool, and its failures are test
/// infrastructure errors, not media results).
fn run_ffmpeg(args: &[String]) -> Vec<u8> {
    let out = std::process::Command::new("ffmpeg")
        .args(args)
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped())
        .output()
        .unwrap_or_else(|e| unreachable!("ffmpeg spawn: {e}"));
    if !out.status.success() {
        unreachable!(
            "ffmpeg failed ({}): {}",
            args.join(" "),
            String::from_utf8_lossy(&out.stderr)
        );
    }
    out.stdout
}

/// Generate one differential lane with ffmpeg 7.1.5's `dnxhd`
/// encoder, raw ES via the `-f dnxhd` muxer — the admission
/// record's exact method (`tools/vta/dnx/README.md`).
pub fn generate_lane(
    name: &str,
    source: &str,
    size: &str,
    bitrate: &str,
    pix_fmt: &str,
    frames: u32,
) -> PathBuf {
    let path = lane_dir().join(format!("{name}.dnxhd"));
    let source_spec = format!("{source}=size={size}:rate=24");
    let args = [
        "-y".to_string(),
        "-v".to_string(),
        "error".to_string(),
        "-f".to_string(),
        "lavfi".to_string(),
        "-i".to_string(),
        source_spec,
        "-frames:v".to_string(),
        frames.to_string(),
        "-c:v".to_string(),
        "dnxhd".to_string(),
        "-b:v".to_string(),
        bitrate.to_string(),
        "-pix_fmt".to_string(),
        pix_fmt.to_string(),
        "-f".to_string(),
        "dnxhd".to_string(),
        path.display().to_string(),
    ];
    run_ffmpeg(&args);
    path
}

/// ffmpeg's own decode of `path` as rawvideo at the stream's native
/// pixel format (yuv422p / yuv422p10le for these lanes; the decoder
/// picks `dnxhd` — no `-c:v` on this side, the reference-side
/// re-encode trap the record's harness honesty note documents).
pub fn ffmpeg_rawvideo(path: &Path) -> Vec<u8> {
    run_ffmpeg(&[
        "-v".to_string(),
        "error".to_string(),
        "-i".to_string(),
        path.display().to_string(),
        "-map".to_string(),
        "0:v".to_string(),
        "-f".to_string(),
        "rawvideo".to_string(),
        "-".to_string(),
    ])
}

/// The MD5 of ffmpeg's decoded output for `path` (the lane-integrity
/// pin: the record committed these per lane in
/// `tools/vta/dnx/evidence/lane-md5s.txt` as the `.ref.raw` MD5s).
pub fn ffmpeg_decode_md5(path: &Path) -> String {
    let out = run_ffmpeg(&[
        "-v".to_string(),
        "error".to_string(),
        "-i".to_string(),
        path.display().to_string(),
        "-map".to_string(),
        "0:v".to_string(),
        "-f".to_string(),
        "hash".to_string(),
        "-hash".to_string(),
        "md5".to_string(),
        "-".to_string(),
    ]);
    let text = String::from_utf8_lossy(&out).trim().to_string();
    text.strip_prefix("MD5=")
        .unwrap_or_else(|| unreachable!("ffmpeg hash output shape: {text}"))
        .to_string()
}

/// A frame sink that keeps every emitted video frame's packed bytes.
#[derive(Default)]
pub struct CaptureSink {
    /// (format-debug, (w, h), packed bytes) per emitted frame.
    pub frames: Vec<(String, (u32, u32), Vec<u8>)>,
}

impl FrameSink for CaptureSink {
    fn accept(&mut self, frame: Frame) -> Result<(), EngineError> {
        let Frame::Video(video) = frame else {
            unreachable!("the DNxHD decoder only emits video frames: {frame:?}");
        };
        let media_types::frame::FrameStorage::Cpu(bytes) = video.data else {
            unreachable!("software decode emits CPU frames: {video:?}");
        };
        self.frames.push((
            format!("{:?}", video.format),
            video.size,
            bytes.as_slice().to_vec(),
        ));
        Ok(())
    }
}

/// One lane's decode through the wired trait path.
pub struct WrapperRun {
    /// The configured decoder (for counters/diagnostics).
    pub decoder: DnxDecoder,
    /// Every emitted frame.
    pub sink: CaptureSink,
}

/// Configure a fresh `DnxDecoder` for the raw-ES packet contract.
fn configured_decoder() -> DnxDecoder {
    let mut decoder = DnxDecoder::new();
    match decoder.configure(&DecoderConfig::new(
        match media_types::ids::CodecDescriptor::new("dnxhd") {
            Ok(d) => d,
            Err(e) => unreachable!("{e:?}"),
        },
        media_types::GenerationId::FIRST,
        ThreadBudget::default(),
        None,
        None,
    )) {
        Ok(()) => decoder,
        Err(err) => unreachable!("configure must accept dnxhd: {err}"),
    }
}

fn packet(chunk: &[u8]) -> Packet {
    Packet {
        track: media_types::TrackId::new(0),
        pts: media_types::Stamp::Missing,
        dts: media_types::Stamp::Missing,
        duration: None,
        data: media_types::packet::SharedBytes::from_vec(chunk.to_vec()),
        keyframe: true,
        discontinuity: false,
        generation: media_types::GenerationId::FIRST,
    }
}

/// Split a raw CBR ES into `frames` same-size chunks (DNxHD's
/// frame = filesize/N; the ES-wiring contract this card documents).
/// `unreachable!`s on a non-divisible file — the lanes are exact
/// CBR multiples by construction (the record's §D).
pub fn cbr_chunks(data: &[u8], frames: usize) -> Vec<&[u8]> {
    if frames == 0 || data.len() % frames != 0 {
        unreachable!(
            "lane must be an exact CBR multiple: {} bytes / {frames}",
            data.len()
        );
    }
    let size = data.len() / frames;
    (0..frames)
        .map(|i| &data[i * size..(i + 1) * size])
        .collect()
}

/// Decode a whole lane through the **wired trait path** (one packet
/// per CBR frame; every call must emit exactly one frame).
pub fn decode_lane(data: &[u8], frames: usize) -> WrapperRun {
    let mut decoder = configured_decoder();
    let mut sink = CaptureSink::default();
    for chunk in cbr_chunks(data, frames) {
        match decoder.decode(packet(chunk), &mut sink) {
            Ok(DecodeOutcome::Emitted { frames: 1 }) => {}
            Ok(other) => unreachable!("one VC-3 frame emits exactly one frame: {other:?}"),
            Err(err) => unreachable!("lane frame must decode: {err}"),
        }
    }
    WrapperRun { decoder, sink }
}

/// Decode lane frame 0 at full depth (the `DnxPicture` seam — the
/// engine-side truth: CID, PAR, interlace, bit depth).
pub fn lane_facts(data: &[u8]) -> DnxPicture {
    let chunk = cbr_chunks(data, 1)[0];
    let mut decoder = configured_decoder();
    match decoder.decode_picture(chunk) {
        Ok(picture) => picture,
        Err(err) => unreachable!("lane frame must decode at full depth: {err}"),
    }
}

/// Decode a whole lane at full depth (the 10-bit lane's path — the
/// trait surface refuses it typed, the picture seam carries it).
pub fn decode_lane_full_depth(data: &[u8], frames: usize) -> Vec<DnxPicture> {
    let mut decoder = configured_decoder();
    cbr_chunks(data, frames)
        .iter()
        .map(|chunk| match decoder.decode_picture(chunk) {
            Ok(picture) => picture,
            Err(err) => unreachable!("lane frame must decode at full depth: {err}"),
        })
        .collect()
}

/// Per-plane differential statistics (ours − theirs, both planar
/// `u16`; the record's §D comparator shape).
#[derive(Debug, Clone, Copy, Default)]
pub struct PlaneStats {
    /// Maximum |Δ| over the plane.
    pub max_delta: i64,
    /// Samples with any difference.
    pub differing: usize,
    /// Total samples in the plane.
    pub total: usize,
    /// Count of exactly −1 deltas.
    pub neg_one: usize,
    /// Count of exactly +1 deltas.
    pub pos_one: usize,
    /// Count of |Δ| ≥ 2.
    pub twos: usize,
}

impl PlaneStats {
    /// The record's rendering extended with the sign histogram
    /// (`Y: maxΔ=2 differing=26038/2073600 (1.256%)` + the
    /// balance evidence).
    pub fn render(&self, name: &str) -> String {
        let pct = if self.total == 0 {
            0.0
        } else {
            100.0 * self.differing as f64 / self.total as f64
        };
        format!(
            "{name}: maxΔ={} differing={}/{} ({pct:.3}%) [−1:{} +1:{} |Δ|≥2:{}]",
            self.max_delta, self.differing, self.total, self.neg_one, self.pos_one, self.twos
        )
    }

    /// Sum two planes' stats (whole-frame aggregation).
    pub fn sum(&mut self, other: &PlaneStats) {
        self.max_delta = self.max_delta.max(other.max_delta);
        self.differing += other.differing;
        self.total += other.total;
        self.neg_one += other.neg_one;
        self.pos_one += other.pos_one;
        self.twos += other.twos;
    }
}

/// Compare two equal-length planar sample arrays.
pub fn compare_plane(ours: &[u16], theirs: &[u16]) -> PlaneStats {
    if ours.len() != theirs.len() {
        unreachable!(
            "plane length parity broken: {} vs {} (the byte-count gate runs first)",
            ours.len(),
            theirs.len()
        );
    }
    let mut stats = PlaneStats {
        total: ours.len(),
        ..PlaneStats::default()
    };
    for (a, b) in ours.iter().zip(theirs) {
        let delta = i64::from(*a) - i64::from(*b);
        let magnitude = delta.abs();
        stats.max_delta = stats.max_delta.max(magnitude);
        if magnitude == 0 {
            continue;
        }
        stats.differing += 1;
        match delta {
            -1 => stats.neg_one += 1,
            1 => stats.pos_one += 1,
            _ => {}
        }
        if magnitude >= 2 {
            stats.twos += 1;
        }
    }
    stats
}

/// Unpack our packed YUYV output back into planar Y/Cb/Cr (the
/// exact inverse of the decoder's lossless repack — byte-identity
/// of the repack is what makes this comparison the record's).
pub fn unpack_yuyv(bytes: &[u8], width: usize, height: usize) -> [Vec<u16>; 3] {
    let cw = width / 2;
    let mut planes = [
        vec![0u16; width * height],
        vec![0u16; cw * height],
        vec![0u16; cw * height],
    ];
    for row in 0..height {
        for c in 0..cw {
            let macro_px = (row * cw + c) * 4;
            planes[0][row * width + 2 * c] = u16::from(bytes[macro_px]);
            planes[1][row * cw + c] = u16::from(bytes[macro_px + 1]);
            planes[0][row * width + 2 * c + 1] = u16::from(bytes[macro_px + 2]);
            planes[2][row * cw + c] = u16::from(bytes[macro_px + 3]);
        }
    }
    planes
}

/// Unpack our packed I420 output into planar Y/Cb/Cr.
pub fn unpack_i420(bytes: &[u8], width: usize, height: usize) -> [Vec<u16>; 3] {
    let cw = width.div_ceil(2);
    let ch = height.div_ceil(2);
    let luma = width * height;
    let chroma = cw * ch;
    [
        bytes[..luma].iter().map(|&b| u16::from(b)).collect(),
        bytes[luma..luma + chroma]
            .iter()
            .map(|&b| u16::from(b))
            .collect(),
        bytes[luma + chroma..]
            .iter()
            .map(|&b| u16::from(b))
            .collect(),
    ]
}

/// Split ffmpeg's rawvideo `yuv422p` output into planar Y/Cb/Cr.
pub fn split_yuv422p(reference: &[u8], width: usize, height: usize) -> [Vec<u16>; 3] {
    let cw = width / 2;
    let luma = width * height;
    let chroma = cw * height;
    [
        reference[..luma].iter().map(|&b| u16::from(b)).collect(),
        reference[luma..luma + chroma]
            .iter()
            .map(|&b| u16::from(b))
            .collect(),
        reference[luma + chroma..]
            .iter()
            .map(|&b| u16::from(b))
            .collect(),
    ]
}

/// Split ffmpeg's rawvideo `yuv422p10le` output into planar u16
/// Y/Cb/Cr (little-endian pairs, the VTA harness's method).
pub fn split_yuv422p10le(reference: &[u8], width: usize, height: usize) -> [Vec<u16>; 3] {
    let cw = width / 2;
    let luma = width * height;
    let chroma = cw * height;
    let samples: Vec<u16> = reference
        .as_chunks::<2>()
        .0
        .iter()
        .map(|b| u16::from_le_bytes(*b))
        .collect();
    [
        samples[..luma].to_vec(),
        samples[luma..luma + chroma].to_vec(),
        samples[luma + chroma..].to_vec(),
    ]
}

/// Assert the record's lane-integrity pin: ffmpeg's decode of the
/// regenerated lane hashes to the committed evidence MD5 (i.e. the
/// lane bytes — deterministic lavfi sources + the same encoder —
/// reproduce the admission record's lanes exactly, so the §D
/// numbers compare lane-for-lane).
pub fn assert_lane_md5(path: &Path, expected: &str) {
    let md5 = ffmpeg_decode_md5(path);
    assert_eq!(
        md5, expected,
        "lane {} must reproduce the admission record's bytes",
        path.display()
    );
}
